import React, { useEffect, useState } from 'react';
import { Link } from 'react-router-dom';

type Product = {
  name: string;
  price: number;
  description: string;
  img: string;
  link?: string;
};

const Home: React.FC = () => {
  const [products, setProducts] = useState<Product[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);

  useEffect(() => {
    fetch('http://localhost:4000/products')
      .then(res => res.json())
      .then(data => {
        setProducts(data);
        setLoading(false);
      })
      .catch(() => {
        setError('Failed to load products');
        setLoading(false);
      });
  }, []);

  return (
    <div style={{ maxWidth: 1200, margin: '0 auto', padding: '32px 16px', fontFamily: 'Inter, Arial, Helvetica, sans-serif' }}>
      <h1 style={{ textAlign: 'center', marginBottom: 32, fontFamily: 'Inter, Arial, Helvetica, sans-serif' }}>
        <span>SUPERCHARGE YOUR </span>
        <span style={{ background: '#fff200', color: '#222', padding: '0 4px', borderRadius: 4 }}>HEALTH</span>
      </h1>
      {loading ? (
        <div style={{ textAlign: 'center', marginTop: 32 }}>Loading products...</div>
      ) : error ? (
        <div style={{ textAlign: 'center', color: 'red', marginTop: 32 }}>{error}</div>
      ) : (
        <div style={{ width: '100%', maxWidth: 900, margin: '0 auto' }}>
          {products.map((p, idx) => (
            <div key={idx} style={{ background: '#fff', borderRadius: 16, boxShadow: '0 2px 8px #eee', maxWidth: 640, width: '100%', padding: 16, margin: '0 auto 32px auto', display: 'flex', flexDirection: 'column', alignItems: 'center' }}>
              <img src={p.img.startsWith('http') ? p.img : `http://localhost:4000${p.img}`} alt={p.name} style={{ width: 600, height: 420, objectFit: 'contain', marginBottom: 24 }} />
              <h3 style={{ fontWeight: 700, marginBottom: 12, fontSize: 28 }}>{p.name}</h3>
              <p style={{ fontSize: 18, color: '#222', marginBottom: 20, textAlign: 'center' }}>{p.description}</p>
              <div style={{ fontWeight: 700, marginBottom: 12, fontSize: 20 }}>USD ${p.price.toFixed(2)} <span style={{ fontWeight: 400, fontSize: 14 }}>Retail</span></div>
              <label style={{ marginBottom: 12, fontSize: 16 }}>
                <input type="checkbox" style={{ marginRight: 8 }} /> Subscribe & save 25%
              </label>
              <button
                style={{ width: '100%', padding: '16px 0', borderRadius: 10, border: '1.5px solid #222', background: '#fff', fontWeight: 700, fontSize: 20, cursor: 'pointer', marginTop: 8 }}
                onClick={() => { if (p.link) window.open(p.link, '_blank'); }}
                disabled={!p.link}
              >
                Add to Cart +
              </button>
            </div>
          ))}
        </div>
      )}
    </div>
  );
};

export default Home;
